catalog_script_client.script:
function onSubmit() {
    var buddy = g_form.getValue('assigned_to');
    var start = g_form.getValue('start_time');
    var end = g_form.getValue('end_time');

    if (!buddy || !start || !end) {
        return true;
    }

    var ga = new GlideAjax('x_travel_buddy_app.TBABuddyAvailabilityAjax');
    ga.addParam('sysparm_name', 'isBuddyAvailable');
    ga.addParam('sysparm_buddy', buddy);
    ga.addParam('sysparm_start', start);
    ga.addParam('sysparm_end', end);
    ga.getXMLWait();

    var answer = ga.getAnswer();
    if (answer == 'false') {
        g_form.addErrorMessage('This Buddy is already booked for the dates you selected. Please choose different dates or a different Buddy.');
        return false;
    }
    return true;
}
